const item = $input.first();
const body = item.json.body;

const toEmail = body.toEmail;
const jdText = body.jdText;
const candidateName = body.candidateName || 'Your resume';
const pdfBase64 = body.pdfBase64;
const pdfFilename = body.pdfFilename || 'resume.pdf';

if (!toEmail) throw new Error('No toEmail field found in payload.');
if (!pdfBase64) throw new Error('No pdfBase64 field found in payload.');

const subject = `Application saved: ${candidateName} \u2014 ${new Date().toISOString().slice(0,10)}`;
const textBody = `Here's a copy of the tailored resume you generated, along with the job description it was tailored for \u2014 so you have a record of exactly what you submitted for this application.\n\n---\nJOB DESCRIPTION\n---\n\n${jdText}\n\n---\n\nSaved automatically by Resume Tailor.`;

const boundary = 'resumeTailorBoundary_' + Date.now();

// RFC 2822 requires base64 body lines wrapped at 76 chars.
function wrap76(b64) {
  return b64.match(/.{1,76}/g).join('\r\n');
}

const mimeMessage = [
  `To: ${toEmail}`,
  `Subject: ${subject}`,
  'MIME-Version: 1.0',
  `Content-Type: multipart/mixed; boundary="${boundary}"`,
  '',
  `--${boundary}`,
  'Content-Type: text/plain; charset="UTF-8"',
  'Content-Transfer-Encoding: 7bit',
  '',
  textBody,
  '',
  `--${boundary}`,
  `Content-Type: application/pdf; name="${pdfFilename}"`,
  'Content-Transfer-Encoding: base64',
  `Content-Disposition: attachment; filename="${pdfFilename}"`,
  '',
  wrap76(pdfBase64),
  '',
  `--${boundary}--`
].join('\r\n');

// Gmail API requires base64url (RFC 4648 \u00a75): + -> -, / -> _, no padding.
const encodedMessage = Buffer.from(mimeMessage, 'utf8')
  .toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=+$/, '');

return [{ json: { raw: encodedMessage } }];

const item = $input.first();
const body = item.json;

// Gmail API returns { "id": "...", "threadId": "..." } on success.
const ok = !!(body && body.id);

return [{
  json: {
    success: ok,
    message: ok ? 'Email sent.' : (body && (body.error?.message || body.message)) || 'Gmail did not confirm the send.'
  }
}];
